#!/usr/bin/env node
// Generates the CSS variables, Tailwind preset and React Native theme from tokens/tokens.json.
// Every declared contrast pair is checked first; if one fails, nothing is written.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(join(root, "tokens", "tokens.json"), "utf8"));
const HEADER =
  "/* GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit. */\n";

// ---- colour helpers ---------------------------------------------------------------------

const hexToRgb = (hex) => {
  const h = hex.replace("#", "");
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
};
const luminance = (hex) => {
  const [r, g, b] = hexToRgb(hex).map((v) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const ratio = (a, b) => {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};
const lookup = (path) => {
  const value = path.split(".").reduce((node, key) => node?.[key], tokens);
  if (typeof value !== "string") throw new Error(`Unknown colour token: ${path}`);
  return value;
};
// "ink.50" -> palette value, "white" -> #FFFFFF, "#abc123" -> itself
const resolve = (ref) => {
  if (ref.startsWith("#")) return ref.toUpperCase();
  if (ref === "white") return tokens.color.white;
  return lookup(`color.${ref}`);
};

// ---- contrast gate ----------------------------------------------------------------------

const failures = [];
const report = [];
const check = (theme, { label, fg, bg, min }, a, b) => {
  const value = ratio(a, b);
  const ok = value + 1e-9 >= min;
  report.push(
    `${ok ? "ok  " : "FAIL"}  ${theme.padEnd(5)} ${value.toFixed(2).padStart(5)}  (min ${min})  ${label}`,
  );
  if (!ok) failures.push(`${theme}: ${label} is ${value.toFixed(2)}:1, needs ${min}:1`);
};
for (const pair of tokens.contrast) check("light", pair, lookup(pair.fg), lookup(pair.bg));
for (const pair of tokens.contrastDark) {
  check("dark", pair, resolve(tokens.themes.dark[pair.fg]), resolve(tokens.themes.dark[pair.bg]));
}
// The light theme's semantic pairs are the same as the palette checks above, but resolve them
// through the theme map too so a re-pointed semantic token cannot slip past the gate.
for (const pair of tokens.contrastDark) {
  const fg = tokens.themes.light[pair.fg];
  const bg = tokens.themes.light[pair.bg];
  if (!fg || !bg) continue;
  check("light", { ...pair, label: `${pair.label} (semantic)` }, resolve(fg), resolve(bg));
}
console.log(report.join("\n"));
if (failures.length > 0) {
  console.error(`\n${failures.length} contrast check(s) failed:\n- ${failures.join("\n- ")}`);
  process.exit(1);
}

// ---- outputs ----------------------------------------------------------------------------

const triplet = (hex) => hexToRgb(hex).join(" ");
const themeVars = (theme, indent = "  ") =>
  Object.entries(theme)
    .map(([name, ref]) => `${indent}--${name}: ${triplet(resolve(ref))};`)
    .join("\n");

const { color, font, radius, size, shadow, motion } = tokens;
const web = radius.web;

const globalsCss = `${HEADER}
:root {
${themeVars(tokens.themes.light)}
  --radius: ${web.control}px;
  --radius-card: ${web.card}px;
  --radius-sheet: ${web.sheet}px;
  --shadow-card: ${shadow.card};
  --shadow-float: ${shadow.float};
  --shadow-sheet: ${shadow.sheet};
  --shadow-focus: ${shadow.focus};
  --ease-standard: ${motion.easing};
  --duration-fast: ${motion.fast}ms;
  --duration-base: ${motion.base}ms;
  --duration-slow: ${motion.slow}ms;
  --font-mono: ${font.monoStack};
  color-scheme: light;
}

/* War Room: a purpose-built dark theme, not an inversion. */
.war-room,
.dark {
${themeVars(tokens.themes.dark)}
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-float: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-focus: 0 0 0 4px rgba(47, 209, 188, 0.28);
  color-scheme: dark;
}

/* Platform admin chrome: ink sidebar and a slim strip across the top. */
[data-surface="admin"] {
  --chrome-sidebar: ${triplet(color.admin.sidebar)};
  --chrome-sidebar-text: ${triplet(color.admin.sidebarText)};
  --chrome-sidebar-muted: ${triplet(color.admin.sidebarMuted)};
  --chrome-strip: ${triplet(color.admin.strip)};
  --chrome-strip-text: ${triplet(color.admin.stripText)};
}

html {
  font-family: ${font.sansStack};
  font-feature-settings: "tnum" 0;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
body {
  background: rgb(var(--canvas));
  color: rgb(var(--foreground));
  font-size: ${tokens.type.web.body.size}px;
  line-height: ${tokens.type.web.body.line}px;
  -webkit-font-smoothing: antialiased;
}
* { border-color: rgb(var(--border)); }

.tabular { font-variant-numeric: tabular-nums; }
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 2px solid rgb(var(--ring));
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
`;

const semanticNames = Object.keys(tokens.themes.light);
const rgbVar = (name) => `rgb(var(--${name}) / <alpha-value>)`;

const paletteFor = (family) =>
  Object.fromEntries(Object.entries(color[family]).map(([k, v]) => [k, v]));

const tailwindPreset = `${HEADER.replace("/*", "//").replace(" */", "")}
import type { Config } from "tailwindcss";

const preset: Partial<Config> = {
  darkMode: ["class", ".war-room"],
  theme: {
    extend: {
      colors: {
        teal: ${JSON.stringify(paletteFor("teal"), null, 8).replace(/\n {6}\}/, "\n        }")},
        ink: ${JSON.stringify(paletteFor("ink"), null, 8).replace(/\n {6}\}/, "\n        }")},
        amber: ${JSON.stringify(paletteFor("amber"))},
        red: ${JSON.stringify(paletteFor("red"))},
        blue: ${JSON.stringify(paletteFor("blue"))},
        series: ${JSON.stringify(Object.fromEntries(color.series.map((v, i) => [String(i + 1), v])))},
        ${semanticNames
          .filter((n) => !n.startsWith("signal-"))
          .map((n) => `${JSON.stringify(n)}: ${JSON.stringify(rgbVar(n))}`)
          .join(",\n        ")},
        signal: {
          ${["teal", "amber", "red", "blue", "ink"]
            .map(
              (f) =>
                `${f}: { soft: ${JSON.stringify(rgbVar(`signal-${f}-soft`))}, mark: ${JSON.stringify(
                  rgbVar(`signal-${f}-mark`),
                )}, text: ${JSON.stringify(rgbVar(`signal-${f}-text`))} }`,
            )
            .join(",\n          ")}
        },
        chrome: {
          sidebar: ${JSON.stringify(rgbVar("chrome-sidebar"))},
          text: ${JSON.stringify(rgbVar("chrome-sidebar-text"))},
          muted: ${JSON.stringify(rgbVar("chrome-sidebar-muted"))},
          strip: ${JSON.stringify(rgbVar("chrome-strip"))},
          "strip-text": ${JSON.stringify(rgbVar("chrome-strip-text"))},
        },
        glow: ${JSON.stringify(color.teal.glow)},
      },
      fontFamily: {
        sans: [${JSON.stringify(font.sansStack)}],
        mono: ["var(--font-mono)"],
      },
      fontSize: {
${Object.entries(tokens.type.web)
  .map(
    ([k, v]) =>
      `        ${JSON.stringify(k)}: [${JSON.stringify(`${v.size}px`)}, { lineHeight: ${JSON.stringify(
        `${v.line}px`,
      )}, fontWeight: ${JSON.stringify(String(v.weight))} }],`,
  )
  .join("\n")}
      },
      borderRadius: {
        sm: "6px",
        md: "var(--radius)",
        lg: "var(--radius-card)",
        xl: "var(--radius-sheet)",
      },
      boxShadow: {
        card: "var(--shadow-card)",
        float: "var(--shadow-float)",
        sheet: "var(--shadow-sheet)",
        focus: "var(--shadow-focus)",
      },
      spacing: {
${tokens.space.map((n) => `        ${JSON.stringify(`s${n}`)}: "${n}px",`).join("\n")}
      },
      transitionTimingFunction: { standard: "var(--ease-standard)" },
      transitionDuration: { fast: "${motion.fast}ms", base: "${motion.base}ms", slow: "${motion.slow}ms" },
      maxWidth: { page: "${size.web.maxWidth}px" },
      width: { sidebar: "${size.web.sidebar}px", "sidebar-collapsed": "${size.web.sidebarCollapsed}px" },
      height: { control: "${size.web.control}px", "control-dense": "${size.web.controlDense}px", topbar: "${size.web.topbar}px", strip: "${size.web.adminStrip}px" },
    },
  },
};

export default preset;
`;

const tailwindV4 = `${HEADER}
@theme {
  --color-teal-50: ${color.teal["50"]};
  --color-teal-100: ${color.teal["100"]};
  --color-teal-200: ${color.teal["200"]};
  --color-teal-300: ${color.teal["300"]};
  --color-teal-400: ${color.teal["400"]};
  --color-teal-500: ${color.teal["500"]};
  --color-teal-600: ${color.teal["600"]};
  --color-teal-700: ${color.teal["700"]};
  --color-teal-800: ${color.teal["800"]};
  --color-teal-900: ${color.teal["900"]};
  --color-teal-950: ${color.teal["950"]};
${Object.entries(color.ink)
  .map(([k, v]) => `  --color-ink-${k}: ${v};`)
  .join("\n")}
${semanticNames.map((n) => `  --color-${n}: rgb(var(--${n}));`).join("\n")}
  --font-sans: ${font.sansStack};
  --font-mono: ${font.monoStack};
  --radius-md: var(--radius);
  --radius-lg: var(--radius-card);
  --radius-xl: var(--radius-sheet);
  --shadow-card: var(--shadow-card);
  --shadow-float: var(--shadow-float);
  --shadow-sheet: var(--shadow-sheet);
}
`;

const write = (rel, content) => {
  const target = join(root, rel);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content);
  console.log(`wrote ${rel}`);
};
write("tokens/globals.css", globalsCss);
write("tokens/tailwind.preset.ts", tailwindPreset);
write("tokens/tailwind-v4.css", tailwindV4);
